/* @lc app=leetcode id=2608 lang=kotlin */ class Solution { fun findShortestCycle(n: Int, edges: Array<IntArray>): Int = edges.flatMap { (a, b) -> listOf(a to b, b to a) }.groupBy({ it.first }, { it.second }).let { g -> (0 until n).map { s -> IntArray(n) { -1 }.also { it[s] = 0 }.let { d -> IntArray(n) { -1 }.let { par -> generateSequence(listOf(s)) { f -> f.flatMap { u -> g[u].orEmpty().filter { v -> d[v] == -1 }.onEach { v -> d[v] = d[u] + 1 }.onEach { v -> par[v] = u } }.takeIf { it.isNotEmpty() } }.flatten().toList().flatMap { u -> g[u].orEmpty().filter { v -> par[u] != v && par[v] != u && d[v] != -1 }.map { v -> d[u] + d[v] + 1 } }.minOrNull() ?: Int.MAX_VALUE } } }.min().let { if (it == Int.MAX_VALUE) -1 else it } } }